import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin, uniqueName } from './helpers';

test.describe(`sales rep: create a deal and move it through pipeline stages`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a rep changes a deal's stage, every team member sees the updated stage within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    // A deal needs a contact to attach to.
    const contactName = uniqueName('contact');
    await pageA.getByTestId('field-name').fill(contactName);
    await pageA.getByTestId('action-add_contact').click();
    await expect(pageA.getByTestId(/^item-contact-/).filter({ hasText: contactName })).toBeVisible({
      timeout: 5_000,
    });

    await pageA.getByTestId('nav-pipeline').click();

    const dealTitle = uniqueName('deal');
    await pageA.getByTestId('field-title').fill(dealTitle);
    await pageA.getByTestId('field-value').fill('5000');
    await pageA.getByTestId('action-create_deal').click();

    const cardA = pageA.getByTestId(/^item-deal-/).filter({ hasText: dealTitle });
    await expect(cardA).toBeVisible({ timeout: 5_000 });

    // Move the deal to a new stage.
    await cardA.getByTestId('field-stage').selectOption('Contacted');

    await pageB.getByTestId('nav-pipeline').click();
    const cardB = pageB.getByTestId(/^item-deal-/).filter({ hasText: dealTitle });
    await expect(cardB.getByTestId('field-stage')).toHaveValue('Contacted', { timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });
});
